-- Private scanner provenance and strict hosted clearance; no external service is provisioned.
CREATE TABLE synapse_gateway.scanner_results(id uuid PRIMARY KEY,provider_scan_id uuid NOT NULL,document_version_id uuid REFERENCES synapse.document_versions(document_version_id),gmail_attachment_id uuid REFERENCES synapse_gateway.gmail_attachments(id),sha256 text NOT NULL CHECK(sha256~'^[a-f0-9]{64}$'),byte_size integer NOT NULL CHECK(byte_size BETWEEN 1 AND 2097152),verdict text NOT NULL CHECK(verdict IN('CLEAN','INFECTED','INDETERMINATE')),engine text NOT NULL CHECK(engine='ClamAV'),engine_version text NOT NULL,scanned_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),actor_id uuid NOT NULL REFERENCES synapse.users(user_id),CHECK((document_version_id IS NOT NULL)<>(gmail_attachment_id IS NOT NULL)));
ALTER TABLE synapse_gateway.scanner_results ENABLE ROW LEVEL SECURITY;ALTER TABLE synapse_gateway.scanner_results FORCE ROW LEVEL SECURITY;
REVOKE ALL ON synapse_gateway.scanner_results FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT(id,provider_scan_id,document_version_id,gmail_attachment_id,sha256,byte_size,verdict,engine,engine_version,scanned_at,recorded_at,actor_id),INSERT(id,provider_scan_id,document_version_id,gmail_attachment_id,sha256,byte_size,verdict,engine,engine_version,scanned_at,actor_id) ON synapse_gateway.scanner_results TO synapse_operations_runtime;
CREATE POLICY phase16_scanner_read ON synapse_gateway.scanner_results FOR SELECT TO synapse_operations_runtime USING(document_version_id IS NOT NULL AND EXISTS(SELECT FROM synapse_gateway.document_bytes b WHERE b.version_id=document_version_id) OR gmail_attachment_id IS NOT NULL AND EXISTS(SELECT FROM synapse_gateway.gmail_attachments a WHERE a.id=gmail_attachment_id));
CREATE POLICY phase16_scanner_insert ON synapse_gateway.scanner_results FOR INSERT TO synapse_operations_runtime WITH CHECK(synapse_gateway.ops_write() AND actor_id=synapse_gateway.ops_actor() AND (document_version_id IS NOT NULL AND EXISTS(SELECT FROM synapse_gateway.document_bytes b WHERE b.version_id=scanner_results.document_version_id AND octet_length(b.bytes)=scanner_results.byte_size AND EXISTS(SELECT FROM synapse.document_versions v WHERE v.document_version_id=b.version_id AND trim(v.sha256_hex)=scanner_results.sha256) AND synapse_gateway.ops_scope(b.case_id,true,true)) OR gmail_attachment_id IS NOT NULL AND EXISTS(SELECT FROM synapse_gateway.gmail_attachments a WHERE a.id=scanner_results.gmail_attachment_id AND a.sha256=scanner_results.sha256 AND octet_length(a.bytes)=scanner_results.byte_size AND synapse_gateway.ops_draft(a.submission_id,true))));
GRANT UPDATE(malware_scan_status) ON synapse.document_versions TO synapse_operations_runtime;
GRANT UPDATE(scan) ON synapse_gateway.gmail_attachments TO synapse_operations_runtime;
CREATE POLICY phase16_scan_update ON synapse_gateway.gmail_attachments FOR UPDATE TO synapse_operations_runtime USING(synapse_gateway.ops_draft(submission_id,true) AND synapse_gateway.ops_submission_visible(submission_id,true)) WITH CHECK(synapse_gateway.ops_write() AND synapse_gateway.ops_draft(submission_id,true) AND scan<>'NOT_REQUIRED' AND (scan<>'CLEAN' OR EXISTS(SELECT FROM synapse_gateway.scanner_results r WHERE r.gmail_attachment_id=gmail_attachments.id AND r.sha256=gmail_attachments.sha256 AND r.verdict='CLEAN')));
ALTER POLICY phase14_update ON synapse.document_versions WITH CHECK(synapse_gateway.ops_write() AND EXISTS(SELECT FROM synapse.documents d WHERE d.document_id=document_versions.document_id AND synapse_gateway.ops_scope(d.owner_case_id,true,true)) AND malware_scan_status<>'NOT_REQUIRED' AND (malware_scan_status<>'CLEAN' OR EXISTS(SELECT FROM synapse_gateway.scanner_results r WHERE r.document_version_id=document_versions.document_version_id AND r.sha256=trim(document_versions.sha256_hex) AND r.verdict='CLEAN')));
ALTER POLICY phase14_update ON synapse.evidence_items WITH CHECK(synapse_gateway.ops_write() AND synapse_gateway.ops_scope(case_id,false,true) AND (evidence_status<>'VERIFIED' OR EXISTS(SELECT FROM synapse.document_versions v WHERE v.document_version_id=evidence_items.document_version_id AND v.malware_scan_status='CLEAN' AND EXISTS(SELECT FROM synapse_gateway.scanner_results r WHERE r.document_version_id=v.document_version_id AND r.sha256=trim(v.sha256_hex) AND r.byte_size=v.byte_size AND r.verdict='CLEAN'))));
-- Existing records are retained. No old NOT_REQUIRED flag alone is accepted by hosted downloads.
